HEAD='<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<title>B1 Today</title>\n<link href="https://fonts.googleapis.com/css2?family=Figtree:wght@400;500;600;700;800&display=swap" rel="stylesheet">\n<link rel="stylesheet" href="frame.css">\n<style>\n  .content { position: absolute; top: 54px; left: 0; right: 0; bottom: 0; padding: 4px 18px 0; display: flex; flex-direction: column; gap: 16px; overflow: hidden; }\n  .head { display: flex; justify-content: space-between; align-items: flex-end; }\n  .date { font-size: 15px; font-weight: 600; color: var(--muted); }\n  h1 { margin: 0; font-size: 34px; font-weight: 800; line-height: 1.1; }\n  .avatar { width: 44px; height: 44px; border-radius: 999px; background: var(--green); color: #fff; display: flex; align-items: center; justify-content: center; font-size: 17px; font-weight: 700; }\n  .card { background: #fff; border: 1px solid var(--line); border-radius: 16px; padding: 14px 16px; }\n  .weather { display: flex; align-items: center; gap: 14px; }\n  .alert { background: var(--orange-soft); border: 1px solid #F3C99A; border-radius: 16px; padding: 14px 16px; display: flex; flex-direction: column; gap: 8px; }\n  .alert .t { font-size: 16px; font-weight: 700; color: #7A3A08; display: flex; gap: 10px; align-items: center; }\n  .alert p { margin: 0; font-size: 14.5px; color: #5C3A1A; line-height: 1.45; }\n  .alert .go { align-self: flex-start; background: var(--orange); color: #fff; font-size: 15px; font-weight: 700; padding: 0 16px; height: 44px; border-radius: 11px; display: flex; align-items: center; }\n  .sec { display: flex; justify-content: space-between; align-items: baseline; }\n  h2 { margin: 0; font-size: 21px; font-weight: 800; }\n  .link { font-size: 15px; font-weight: 700; color: var(--green); }\n  .chip { font-size: 12.5px; font-weight: 700; padding: 3px 9px; border-radius: 999px; }\n  .meta { font-size: 13px; font-weight: 600; color: var(--muted); }\n  .action { display: flex; flex-direction: column; gap: 9px; }\n  .action .title { font-size: 17px; font-weight: 700; line-height: 1.3; }\n  .action .sub { font-size: 14px; color: var(--muted); line-height: 1.45; }\n  .btns { display: flex; gap: 10px; }\n  .btns .btn { height: 44px; font-size: 15px; border-radius: 11px; }\n  .tab { position: absolute; left: 0; right: 0; bottom: 0; z-index: 40; background: rgba(255,255,255,.97); border-top: 1px solid var(--line); padding: 8px 6px 30px; display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); align-items: end; }\n  .tab a { color: var(--muted); display: flex; flex-direction: column; align-items: center; gap: 3px; font-size: 11.5px; font-weight: 600; }\n  .tab a.on { color: var(--green); font-weight: 800; }\n  .tab .cam { width: 58px; height: 58px; border-radius: 999px; background: var(--green); display: flex; align-items: center; justify-content: center; margin: -26px auto 0; border: 4px solid var(--bg); box-shadow: 0 4px 10px rgba(45,106,58,.35); }\n'
